package com.sih.support.service; import static org.junit.jupiter.api.Assertions.*; import com.sih.shared.tenant.TenantContext; import com.sih.support.dto.SupportDtos.*; import java.time.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.*; import org.springframework.web.server.*; @SpringBootTest class SupportWorkflowServiceIT {@Autowired SupportWorkflowService s;@AfterEach void x(){TenantContext.clear();}@Test void deliversMealInControlledSequence(){TenantContext.setCurrentTenant("hospital-a");var m=s.createMeal(new MealReq("P-1","DIABETIQUE","DEJEUNER",LocalDate.now(),"B-1"));assertThrows(ResponseStatusException.class,()->s.deliver(m.id()));assertEquals("DELIVERED",s.deliver(s.prepare(m.id()).id()).status());}@Test void tenantCannotAccessOtherEquipment(){TenantContext.setCurrentTenant("hospital-a");var a=s.createEquipment(new EquipmentReq("EQ-A","Respirateur","Réanimation",true));TenantContext.setCurrentTenant("hospital-b");assertTrue(s.equipment().isEmpty());assertThrows(ResponseStatusException.class,()->s.createWork(new WorkReq(a.id(),"Contrôle","PREVENTIVE",LocalDate.now(),null)));}}